-- ------------------------------------------------------------
-- Proc on Heroic Strike, Thunder Clap and Cleave
-- ------------------------------------------------------------
-- SpellFamilyMask0 4194496 = 0x40 Heroic Strike | 0x80 Thunder Clap
-- | 0x400000 Cleave.  This is stock Incite's own mask -- retail's version
-- buffed exactly these three abilities -- so it is restored rather than
-- invented, and it covers every rank of all three.
--
-- ProcFlags 16 = PROC_FLAG_DONE_SPELL_MELEE_DMG_CLASS.  All three are melee
-- damage-class abilities the player casts.
--
-- SpellPhaseMask 2 (PROC_SPELL_PHASE_HIT) is mandatory -- a row with 0 silently
-- never triggers.
--
-- Chance 0 means "fall back to the spell's ProcChance", which is 101 = always.
-- The real roll is the player's block chance and it lives in the script, since
-- no spell_proc column can reference a character stat.
--
-- AttributesMask is deliberately NOT 2: these are real player casts, not
-- triggered children, so PROC_ATTR_TRIGGERED_CAN_PROC is not needed.
DELETE FROM `spell_proc` WHERE `SpellId` = -50685;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(-50685, 0, 4, 4194496, 0, 0, 16, 0, 2, 0, 0, 0, 0, 0, 0, 0);

