-- ------------------------------------------------------------
-- Both scripts from the previous design are gone: spell_warr_incite_revenge on
-- the three ranks, and spell_warr_mocking_blow_incite_cd on -694.  Mocking Blow
-- keeps the cooldown it has; nothing else referenced it.
DELETE FROM `spell_script_names` WHERE `ScriptName` IN ('spell_warr_incite_revenge', 'spell_warr_mocking_blow_incite_cd', 'spell_warr_incite');
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
